// Precompiled Shader Cache Implementation
// Loads cache generated by XenosRecomp (6404 shaders, Vulkan SPIR-V)
// Uses ZSTD decompression + smol-v decoding like UnleashedRecomp

#include "shader_cache.h"
#include "../thirdparty/zstd/zstd.h"
#include "../thirdparty/smol-v/smolv.h"

#include <algorithm>
#include <cstring>
#include <rex/logging.h>

// Include zstd decompressor implementation (single file)
#define ZSTD_DECODER_IMPLEMENTATION
// We use separate zstddeclib.c, so don't need to include here, just link
// The header zstd.h provides ZSTD_decompress

namespace sonic_native {
namespace hedgehog {

ShaderCache& ShaderCache::Get() {
    static ShaderCache instance;
    return instance;
}

bool ShaderCache::Initialize() {
    if (initialized_) return true;
    
    REXLOG_INFO("ShaderCache: initializing - expecting 6404 shaders from XenosRecomp");
    
    if (g_shaderCacheEntryCount == 0) {
        REXLOG_WARN("ShaderCache: no embedded cache (g_shaderCacheEntryCount=0)");
        initialized_ = true;
        return false;
    }
    
    REXLOG_INFO("ShaderCache: found {} entries, compressed SPIR-V {} -> {} bytes",
                g_shaderCacheEntryCount, g_spirvCacheCompressedSize, g_spirvCacheDecompressedSize);
    
    // Build hash map for fast lookup (sorted array in generated file, but we use hash map)
    rawEntries_.reserve(g_shaderCacheEntryCount);
    for (size_t i = 0; i < g_shaderCacheEntryCount; ++i) {
        const auto& entry = g_shaderCacheEntries[i];
        rawEntries_[entry.hash] = &entry;
    }
    
    // Decompress global ZSTD cache (once)
    if (!DecompressGlobalCache()) {
        REXLOG_ERROR("ShaderCache: failed to decompress global cache");
        initialized_ = true;
        return false;
    }
    
    stats_.totalShaders = g_shaderCacheEntryCount;
    stats_.decompressedCacheSize = decompressedCacheSize_;
    stats_.memoryUsage = decompressedCacheSize_ + rawEntries_.size() * sizeof(ShaderCacheEntry);
    
    REXLOG_INFO("ShaderCache: initialized with {} shaders, decompressed {} bytes, complete={}",
                rawEntries_.size(), decompressedCacheSize_, IsComplete() ? "YES" : "NO");
    
    if (!IsComplete()) {
        REXLOG_WARN("ShaderCache: incomplete, expected 6404 shaders");
    }
    
    initialized_ = true;
    return true;
}

void ShaderCache::Shutdown() {
    if (!initialized_) return;
    
    {
        std::lock_guard<std::mutex> lock(cacheMutex_);
        decodedCache_.clear();
    }
    rawEntries_.clear();
    decompressedCache_.reset();
    decompressedCacheSize_ = 0;
    stats_ = {};
    initialized_ = false;
    
    REXLOG_INFO("ShaderCache: shutdown");
}

bool ShaderCache::DecompressGlobalCache() {
    if (g_spirvCacheCompressedSize == 0 || g_spirvCacheDecompressedSize == 0) {
        REXLOG_WARN("ShaderCache: no compressed SPIR-V cache");
        return false;
    }
    
    decompressedCache_ = std::make_unique<uint8_t[]>(g_spirvCacheDecompressedSize);
    decompressedCacheSize_ = g_spirvCacheDecompressedSize;
    
    size_t result = ZSTD_decompress(decompressedCache_.get(), g_spirvCacheDecompressedSize,
                                    g_compressedSpirvCache, g_spirvCacheCompressedSize);
    
    if (ZSTD_isError(result)) {
        REXLOG_ERROR("ShaderCache: ZSTD_decompress failed: {}", ZSTD_getErrorName(result));
        decompressedCache_.reset();
        decompressedCacheSize_ = 0;
        return false;
    }
    
    if (result != g_spirvCacheDecompressedSize) {
        REXLOG_WARN("ShaderCache: ZSTD decompressed size mismatch: got {} expected {}",
                    result, g_spirvCacheDecompressedSize);
        decompressedCacheSize_ = result;
    }
    
    REXLOG_INFO("ShaderCache: ZSTD decompressed {} -> {} bytes", g_spirvCacheCompressedSize, result);
    return true;
}

bool ShaderCache::DecodeShader(const ShaderCacheEntry& raw, DecodedShader& out) const {
    if (!decompressedCache_ || raw.spirvSize == 0) {
        return false;
    }
    
    if (raw.spirvOffset + raw.spirvSize > decompressedCacheSize_) {
        REXLOG_ERROR("ShaderCache: shader {:x} offset {}+{} out of bounds {}", raw.hash, raw.spirvOffset, raw.spirvSize, decompressedCacheSize_);
        return false;
    }
    
    const uint8_t* compressedData = decompressedCache_.get() + raw.spirvOffset;
    
    // smol-v decode: first get decoded size
    size_t decodedSize = smolv::GetDecodedBufferSize(compressedData, raw.spirvSize);
    if (decodedSize == 0) {
        REXLOG_ERROR("ShaderCache: shader {:x} smol-v GetDecodedBufferSize failed (size {})", raw.hash, raw.spirvSize);
        return false;
    }
    
    std::vector<uint8_t> decodedBytes(decodedSize);
    bool success = smolv::Decode(compressedData, raw.spirvSize, decodedBytes.data(), decodedSize);
    
    if (!success) {
        REXLOG_ERROR("ShaderCache: shader {:x} smol-v Decode failed", raw.hash);
        return false;
    }
    
    // SPIR-V is uint32_t array
    if (decodedSize % 4 != 0) {
        REXLOG_WARN("ShaderCache: shader {:x} decoded size {} not multiple of 4", raw.hash, decodedSize);
    }
    
    out.hash = raw.hash;
    out.spirv.resize(decodedSize / 4);
    std::memcpy(out.spirv.data(), decodedBytes.data(), decodedSize);
    out.specConstantsMask = raw.specConstantsMask;
    out.name = raw.name ? raw.name : "";
    out.isValid = true;
    
    // Infer stage from name or keep generic
    // In XenosRecomp, stage is not directly stored in this format, but we can guess:
    // For Generations, most are pixel shaders (stage 2 in old format)
    // We set stage based on hash? For now set 0, translator will handle
    out.stage = 0;
    
    return true;
}

const DecodedShader* ShaderCache::Find(uint64_t hash) const {
    // Fast path: check decoded cache
    {
        std::lock_guard<std::mutex> lock(cacheMutex_);
        auto it = decodedCache_.find(hash);
        if (it != decodedCache_.end()) {
            // stats_.cacheHits++ // mutable not allowed in const, skip or use atomic
            return &it->second;
        }
    }
    
    // Find raw entry
    auto rawIt = rawEntries_.find(hash);
    if (rawIt == rawEntries_.end()) {
        return nullptr;
    }
    
    const ShaderCacheEntry* raw = rawIt->second;
    
    // Decode on demand
    DecodedShader decoded;
    if (!DecodeShader(*raw, decoded)) {
        return nullptr;
    }
    
    // Insert into decoded cache
    {
        std::lock_guard<std::mutex> lock(cacheMutex_);
        auto [it, inserted] = decodedCache_.emplace(hash, std::move(decoded));
        return &it->second;
    }
}

const ShaderCacheEntry* ShaderCache::FindRaw(uint64_t hash) const {
    auto it = rawEntries_.find(hash);
    if (it != rawEntries_.end()) {
        return it->second;
    }
    return nullptr;
}

void ShaderCache::DumpInfo() const {
    REXLOG_INFO("ShaderCache Info:");
    REXLOG_INFO("  Total shaders: {} (expected 6404)", rawEntries_.size());
    REXLOG_INFO("  Complete: {}", IsComplete() ? "YES" : "NO");
    REXLOG_INFO("  Decompressed cache: {} bytes", decompressedCacheSize_);
    REXLOG_INFO("  Decoded cache entries: {}", decodedCache_.size());
    REXLOG_INFO("  Memory usage: {} bytes", stats_.memoryUsage);
    
    size_t vsCount = 0, psCount = 0;
    for (auto& pair : rawEntries_) {
        // Heuristic: if name contains _v or vertex, count as VS
        // For Generations, most are pixel shaders
        if (pair.second->name && std::string(pair.second->name).find("_v") != std::string::npos) {
            vsCount++;
        } else {
            psCount++;
        }
    }
    REXLOG_INFO("  Estimated VS: {}, PS: {}", vsCount, psCount);
}

} // namespace hedgehog
} // namespace sonic_native
